class Solution {
public:
    int dieSimulator(int n, vector<int>& rollMax) {
        const long long MOD = 1000000007;
        long long dp[6][16] = {0};
        for (int i = 0; i < 6; i++) dp[i][1] = 1;

        for (int step = 1; step < n; step++) {
            long long ndp[6][16] = {0};
            long long total = 0;
            for (int f = 0; f < 6; f++)
                for (int c = 1; c <= rollMax[f]; c++)
                    total = (total + dp[f][c]) % MOD;
            for (int j = 0; j < 6; j++) {
                long long same = 0;
                for (int c = 1; c <= rollMax[j]; c++)
                    same = (same + dp[j][c]) % MOD;
                ndp[j][1] = (total - same + MOD) % MOD;
                for (int c = 2; c <= rollMax[j]; c++)
                    ndp[j][c] = dp[j][c - 1];
            }
            for (int f = 0; f < 6; f++)
                for (int c = 0; c < 16; c++)
                    dp[f][c] = ndp[f][c];
        }

        long long ans = 0;
        for (int f = 0; f < 6; f++)
            for (int c = 1; c <= rollMax[f]; c++)
                ans = (ans + dp[f][c]) % MOD;
        return (int)ans;
    }
};
